$('#import-config').addEventListener('click',()=>$('#file-config').click());
$('#file-config').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30e6)throw new Error('Scenario file is too large (30 MB maximum)');const input=JSON.parse(await file.text());if(!input.config && !('frequencyGHz' in input))throw new Error('Expected an exported scenario or configuration object');config=validateConfig(input.config||input);activePreset=config.scenario;provenance=Object.fromEntries(Object.keys(config).map(k=>[k,'Imported user input; unverified']));invalidateAnalysis();populate();recalculate(false);toast('Scenario imported and recalculated');}catch(err){toast(err.message,true);}e.target.value='';});
$('#import-pattern').addEventListener('click',()=>$('#file-pattern').click());$('#file-pattern').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw new Error('Pattern file too large (2 MB maximum)');config.pattern=parsePatternCSV(await file.text());config.patternGrid=null;provenance.pattern=`Imported file: ${file.name}; source unverified`;invalidateAnalysis();recalculate(false);toast(`Imported ${config.pattern.length} pattern samples`);}catch(err){toast(err.message,true);}e.target.value='';});
