$('#run-thermal').addEventListener('click',()=>{thermal=runThermal(config,Number($('#thermal-hours').value));const lost=thermal.frames.find(f=>!f.powered);$('#thermal-results').innerHTML=`<span>Minimum <b>${fmt(thermal.minTemp,1)} °C</b></span><span>Maximum <b>${fmt(thermal.maxTemp,1)} °C</b></span><span>Heater energy <b>${fmt(thermal.heaterWh,2)} Wh</b></span><span>Battery <b>${lost?`depleted by ${fmt(lost.hours,1)} h`:'not depleted'}</b></span>`;drawThermal();});
$('#thermal-hours').addEventListener('change',()=>{thermal=null;$('#thermal-results').textContent='Duration changed. Run thermal study again.';const canvas=$('#thermal-chart');canvas.getContext('2d').clearRect(0,0,canvas.width,canvas.height);});
function wilson(success,n){const z=1.96,p=success/n,d=1+z*z/n,mid=(p+z*z/(2*n))/d,half=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return `${fmt((mid-half)*100,1)}–${fmt((mid+half)*100,1)}%`;}
$('#run-batch').addEventListener('click',()=>{if(worker)worker.terminate();batch=null;$('#export-batch').disabled=true;$('#batch-results').textContent='Analysis running…';worker=new Worker(new URL('./analysis.worker.js',import.meta.url),{type:'module'});$('#run-batch').disabled=true;$('#cancel-batch').hidden=false;$('#batch-progress').hidden=false;$('#batch-progress i').style.width='0%';$('#batch-status').textContent='Sampling landing conditions…';const count=Number($('#batch-count').value);
  worker.onmessage=({data})=>{if(data.type==='progress'){$('#batch-progress i').style.width=`${data.done/data.count*100}%`;$('#batch-status').textContent=`Simulating ${data.done} / ${data.count} paired scenarios…`;}
    if(data.type==='done'){batch=data;const n=data.rows.length,g=data.rows.filter(r=>r.pass).length,f=data.rows.filter(r=>r.fixedPass).length;$('#batch-results').innerHTML=table([['Passed trials',`${g} / ${n}`,`${f} / ${n}`],['Scenario pass rate',`${fmt(g/n*100,1)}%`,`${fmt(f/n*100,1)}%`],['95% Wilson interval',wilson(g,n),wilson(f,n)]],['Metric','Gimbal','Fixed'])+`<p class="small-note">Seed ${data.seed} · success means ≥95% post-acquisition-window link availability. Intervals apply only to the declared sampling distribution. Uniform Euler angles are not uniform orientations on a sphere.</p>`;$('#batch-status').textContent=`Completed ${n} paired scenarios · seed ${data.seed}`;$('#export-batch').disabled=false;scatterChart($('#batch-chart'),data.rows);finishBatch();}
    if(data.type==='error'){toast(data.message,true);finishBatch();}};
  worker.onerror=e=>{toast(e.message||'Analysis worker failed',true);finishBatch();};worker.postMessage({config,count,seed:config.seed});
});
function finishBatch(){worker?.terminate();worker=null;$('#run-batch').disabled=false;$('#cancel-batch').hidden=true;$('#batch-progress').hidden=true;}
$('#cancel-batch').addEventListener('click',()=>{finishBatch();$('#batch-status').textContent='Analysis cancelled. No partial result is presented.';$('#batch-results').textContent='Run again to produce a complete batch.';});
